import torch
import torch.nn as nn
import avelang
import avelang.language as al


@avelang.jit
def matmul_kernel(
    a: al.Tensor((4096, 4096), al.bf16),
    b: al.Tensor((4096, 4096), al.bf16),
    c: al.Tensor((4096, 4096), al.bf16),
):
    pid_m = al.block_id(0)
    pid_n = al.block_id(1)
    tid_m = al.thread_id(0)
    tid_n = al.thread_id(1)

    # Shared memory tiles
    a_tile = al.make_shared((32, 16), al.bf16)
    b_tile = al.make_shared((16, 32), al.bf16)

    row = pid_m * 32 + tid_m
    col = pid_n * 32 + tid_n

    acc = al.convert(0.0, al.f32)

    for k_block in al.range(0, 4096, 16):
        # Collaborative load of A tile
        if tid_n < 16:
            a_row = pid_m * 32 + tid_m
            a_col = k_block + tid_n
            if a_row < 4096 and a_col < 4096:
                a_tile[tid_m, tid_n] = a[a_row, a_col]
            else:
                a_tile[tid_m, tid_n] = al.convert(0.0, al.bf16)

        # Collaborative load of B tile
        if tid_m < 16:
            b_row = k_block + tid_m
            b_col = pid_n * 32 + tid_n
            if b_row < 4096 and b_col < 4096:
                b_tile[tid_m, tid_n] = b[b_row, b_col]
            else:
                b_tile[tid_m, tid_n] = al.convert(0.0, al.bf16)

        al.syncthreads()

        # Compute dot product
        if row < 4096 and col < 4096:
            for k in al.range(0, 16):
                a_val = al.convert(a_tile[tid_m, k], al.f32)
                b_val = al.convert(b_tile[k, tid_n], al.f32)
                acc = acc + a_val * b_val

        al.syncthreads()

    if row < 4096 and col < 4096:
        c[row, col] = al.convert(acc, al.bf16)


def avelang_matmul(A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
    A_dev = A.to(torch.bfloat16).contiguous()
    B_dev = B.to(torch.bfloat16).contiguous()
    C_dev = torch.empty(4096, 4096, dtype=torch.bfloat16, device=A.device)

    grid = (128, 128, 1)
    block = (32, 32, 1)

    matmul_kernel[lambda: (grid, block)](A_dev, B_dev, C_dev)
    return C_dev


class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return avelang_matmul(A, B)
